/// A device of the configuration: adapter, base address, vector and
/// the bus request level.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Instance {
    pub adapter: u32,
    pub base: u32,
    pub vector: u32,
    pub br: u32,
}

